.cr_rp_target<-function(target){if(!.cr_object(target)) .cr_error('RETAIL_TARGET','Explicit retail default target required');.cr_data_required(target,c('event','horizon','time_unit','probability_measure','conditioning','default_unit','default_definition','currency'));if(target$event!='default'||target$time_unit!='days'||target$probability_measure!='PHYSICAL'||target$conditioning!='not_defaulted_at_index'||!(target$default_unit%in%c('facility','obligor'))) .cr_error('RETAIL_TARGET','Require physical day-horizon default target with explicit performing default unit');.cr_data_days(target$horizon,'target.horizon',1);.cr_rf_text(target$default_definition,'default_definition');.cr_rf_text(target$currency,'currency');target}
