.cr_rp_context<-function(ctx,target){for(k in c('horizon','time_unit','probability_measure','conditioning','currency'))if(!is.null(ctx[[k]])&&!identical(ctx[[k]],target[[k]])&&!(is.numeric(ctx[[k]])&&is.numeric(target[[k]])&&ctx[[k]]==target[[k]])) .cr_error('TARGET_MISMATCH',paste('Context differs from pool target',k))}
.cr_rp_features<-function(row,fields,score,segments){if(any(vapply(c(fields,score),function(k)is.null(row[[k]]),logical(1))))return(list(segment=NULL,index=NULL,status='MISSING_FEATURE'));for(k in fields) .cr_rf_text(row[[k]],k);key<-.cr_data_key(row,fields);matches<-Filter(function(s).cr_data_key(s$values,fields)==key,segments);if(!length(matches))return(list(segment=NULL,index=NULL,status='UNSEEN_STRATUM'));segment<-matches[[1]];x<-.cr_rf_number(row[[score]],score);if(!(segment$score_min<=x&&x<=segment$score_max))return(list(segment=segment,index=NULL,status='OUTSIDE_SCORE_DOMAIN'));list(segment=segment,index=sum(unlist(segment$cutpoints,use.names=FALSE)<=x),status='COVERED')}
