.cr_rp_support<-function(stats,spec){keys<-c(minimum_cases='cases',minimum_defaults='defaults',minimum_lgd_count='lgd_count',minimum_ead_count='ead_count');names(keys)[vapply(names(keys),function(k)stats[[keys[[k]]]]<spec[[k]],logical(1))]}

fit_retail_risk_pools<-function(observations,pooling_spec,target,training,model_id,model_version,context=NULL){target<-.cr_rp_target(target);spec<-.cr_rp_spec(pooling_spec);fields<-spec$fields;score<-spec$score;segments<-spec$segments;if(!.cr_object(training)||!identical(training$role,'TRAIN')) .cr_error('RETAIL_TRAINING','Training metadata must explicitly identify TRAIN role');.cr_data_required(training,c('known_at','split_id','data_fingerprint'));cutoff<-.cr_data_date(training$known_at,'training.known_at');ctx<-.cr_rf_cutoffs(training$known_at,training$known_at,context)$context;.cr_rp_context(ctx,target);if(.cr_data_date(pooling_spec$known_at,'pooling_spec.known_at')>cutoff) .cr_error('RETAIL_DATE','Pool specification unavailable at training cutoff');rows<-.cr_data_rows(observations,'observations');.cr_data_unique(rows,'observation_id','observations');.cr_data_unique(rows,'default_unit_id','default units');bins<-setNames(lapply(segments,function(s)rep(list(list()),length(s$cutpoints)+1L)),vapply(segments,`[[`,character(1),'segment_id'))
 for(row in rows){.cr_data_required(row,c('default_unit_id','role','index_date','feature_observed_at','feature_known_at','label_window_end','label_known_at','defaulted','lgd_status'));if(!all(c('default_date','lgd','ead','lgd_known_at','ead_known_at')%in%names(row))) .cr_error('RETAIL_TARGET','Default date and LGD/EAD outcomes/knowledge dates require explicit nullable fields');if(row$role!='TRAIN'||!is.logical(row$defaulted)||length(row$defaulted)!=1||is.na(row$defaulted)) .cr_error('RETAIL_TRAINING','Only explicit TRAIN rows with boolean outcomes allowed');index<-.cr_data_date(row$index_date,'index_date');observed<-.cr_data_date(row$feature_observed_at,'feature_observed_at');known<-.cr_data_date(row$feature_known_at,'feature_known_at');end<-.cr_data_date(row$label_window_end,'label_window_end');label_known<-.cr_data_date(row$label_known_at,'label_known_at');if(!(observed<=known&&known<=index&&index<end&&end<=label_known&&label_known<=cutoff)||as.numeric(end-index)!=target$horizon) .cr_error('RETAIL_DATE','Training features must predate the mature declared outcome horizon and cutoff');if(!(row$lgd_status%in%c('CLOSED','OPEN','NOT_DEFAULTED'))||(!row$defaulted&&(row$lgd_status!='NOT_DEFAULTED'||!is.null(row$lgd)||!is.null(row$ead)))||(row$defaulted&&row$lgd_status=='NOT_DEFAULTED')||(row$lgd_status!='CLOSED'&&!is.null(row$lgd))) .cr_error('RETAIL_TARGET','LGD/EAD conditioning and open-workout status inconsistent');default<-if(is.null(row$default_date))NULL else .cr_data_date(row$default_date,'default_date');if((row$defaulted&&(is.null(default)||!(index<default&&default<=end)))||(!row$defaulted&&!is.null(default))) .cr_error('RETAIL_TARGET','Training default date must match the horizon outcome');for(parameter in c('lgd','ead')){known_value<-row[[paste0(parameter,'_known_at')]];if(is.null(row[[parameter]])){if(!is.null(known_value)) .cr_error('RETAIL_TARGET','Missing numeric outcome must have null knowledge date')}else if(is.null(known_value)||!(default<=.cr_data_date(