 merge_candidate<-function(i){left<-blocks[[i]];right<-blocks[[i+1L]];merged<-list(first=left$first,last=right$last,rows=c(left$rows,right$rows));s<-summary(merged);if(any(vapply(names(s$spread),function(k)!is.null(pooling_spec$maximum_bin_mean_spread[[k]])&&!is.null(s$spread[[k]])&&s$spread[[k]]>pooling_spec$maximum_bin_mean_spread[[k]],logical(1))))return(NULL);lm<-.cr_rp_stats(left$rows)$means;rm<-.cr_rp_stats(right$rows)$means;cost<-.cr_loss_sum(vapply(names(lm),function(k)if(is.null(lm[[k]])||is.null(rm[[k]]))0 else {scale<-max(1,abs(lm[[k]]),abs(rm[[k]]));(lm[[k]]/scale-rm[[k]]/scale)^2},numeric(1)));list(cost=cost,index=i,merged=merged,stats=s$stats,spread=s$spread)}
 while(length(blocks)>1){candidates<-list();for(i in seq_along(blocks))if(length(.cr_rp_support(.cr_rp_stats(blocks[[i]]$rows),pooling_spec)))for(j in c(i-1L,i))if(j>=1&&j<length(blocks)){candidate<-merge_candidate(j);if(!is.null(candidate))candidates[[length(candidates)+1L]]<-list(priority=0,cost=candidate$cost,index=j,reason='MINIMUM_SUPPORT',candidate=candidate)};if(!length(candidates))for(i in seq_len(length(blocks)-1L)){lm<-.cr_rp_stats(blocks[[i]]$rows)$means;rm<-.cr_rp_stats(blocks[[i+1L]]$rows)$means;violated<-names(Filter(function(k){order<-segment$monotonicity[[k]];!is.null(lm[[k]])&&!is.null(rm[[k]])&&((order=='increasing'&&lm[[k]]>rm[[k]])||(order=='decreasing'&&lm[[k]]<rm[[k]]))},setNames(as.list(names(segment$monotonicity)),names(segment$monotonicity))));if(length(violated)){candidate<-merge_candidate(i);if(!is.null(candidate))candidates[[length(candidates)+1L]]<-list(priority=1,cost=candidate$cost,index=i,reason=paste0('MONOTONICITY:',paste(sort(violated),collapse=',')),candidate=candidate)}};if(!length(candidates))break;choice<-.cr_rf_sort(candidates,c('priority','cost','index'))[[1]];i<-choice$index;c<-choice$candidate;merge_path[[length(merge_path)+1L]]<-list(segment_id=segment$segment_id,left_first=blocks[[i]]$first,left_last=blocks[[i]]$last,right_first=blocks[[i+1L]]$first,right_last=blocks[[i+1L]]$last,reason=choice$reason,merged_statistics=c$stats,merged_bin_mean_spread=c$spread);blocks<-append(blocks[-c(i,i+1L)],list(c$merged),after=i-1L)}
 pools<-list();violations<-list();for(block in blocks){s<-summary(block);support<-.cr_rp_support(s$stats,pooling_spec);pool_id<-paste0(model_id,'@',model_version,':',substr(rule_hash,1,12),':',segment$segment_id,':',block$first,'-',block$last);pools[[length(pools)+1L]]<-list(pool_id=pool_id,first_bin=block$first,last_bin=block$last,statistics=s$stats,initial_bin_mean_spread=s$spread,support_violations=as.list(support));if(length(support))violations[[length(violations)+1L]]<-list(kind='INSUFFICIENT_SUPPORT',pool_id=pool_id,constraints=as.list(support))};if(length(pools)>1)for(i in seq_len(length(pools)-1L))for(k in names(segment$monotonicity)){left<-pools[[i]];right<-pools[[i+1L]];order<-segment$monotonicity[[k]];a<-left$statistics$means[[k]];b<-right$statistics$means[[k]];if(!is.null(a)&&!is.null(b)&&((order=='increasing'&&a>b)||(order=='decreasing'&&a<b)))violations[[length(violations)+1L]]<-list(kind='MONOTONICITY',left_pool=left$pool_id,right_pool=right$pool_id,parameter=k,direction=order)};fitted[[length(fitted)+1L]]<-list(segment_id=segment$segment_id,values=segment$values,score_min=segment$score_min,score_max=segment$score_max,cutpoints=as.list(unlist(segment$cutpoints,use.names=FALSE)),monotonicity=segment$monotonicity,status=if(!length(violations))'APPLICABLE'else 'INSUFFICIENT_SUPPORT',pools=pools,violations=violations,initial_bin_statistics=initial_stats)}
