.cr_rp_checked<-function(model){model<-.cr_model(model);if(model$method_id!='retail_features.fit_retail_risk_pools') .cr_error('RETAIL_ARTIFACT','Expected frozen retail pooling model');unbound<-model;digest<-unbound$artifact_hash;unbound$artifact_hash<-NULL;if(!identical(digest,.cr_hash(unbound))) .cr_error('INTEGRITY_ERROR','Pooling model content differs from its binding');.cr_rp_target(model$target);.cr_rp_spec(model$parameters$pooling_spec);model}
assign_retail_risk_pool<-function(observations,fitted_model,as_of,information_cutoff,expected_target,uncovered_policy,context=NULL){model<-.cr_rp_checked(fitted_model);times<-.cr_rf_cutoffs(as_of,information_cutoff,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;.cr_rp_context(ctx,model$target);if(!identical(.cr_hash(expected_target),.cr_hash(model$target))) .cr_error('TARGET_MISMATCH','Pool target differs from expected target');if(.cr_data_date(model$training$known_at,'training.known_at')>cutoff) .cr_error('RETAIL_DATE','Pooling model unavailable at scoring cutoff');if(!(uncovered_policy%in%c('unassigned','error'))) .cr_error('RETAIL_POOL','Declare unassigned or error uncovered-profile policy');p<-model$parameters;fields<-unlist(p$stratum_fields,use.names=FALSE);score<-p$score_field;rows<-.cr_data_rows(observations,'observations');.cr_data_unique(rows,'observation_id','observations');outputs<-list();for(row in rows){.cr_data_required(row,c('index_date','feature_observed_at','feature_known_at'));index<-.cr_data_date(row$index_date,'index_date');observed<-.cr_data_date(row$feature_observed_at,'feature_observed_at');known<-.cr_data_date(row$feature_known_at,'feature_known_at');if(!(observed<=known&&known<=index&&index<=anchor)||known>cutoff) .cr_error('RETAIL_DATE','Scoring features must be available by their dated index and cutoff');match<-.cr_rp_features(row,fields,score,p$segments);segment<-match$segment;bin_index<-match$index;status<-match$status;pool<-NULL;if(status=='COVERED'){if(segment$status!='APPLICABLE')status<-'INSUFFICIENT_SUPPORT'else pool<-Filter(function(s)s$first_bin<=bin_index&&bin_index<=s$last_bin,segment$pools)[[1]]};if(status!='COVERED'&&uncovered_policy=='error') .cr_error('RETAIL_UNCOVERED','Observation not covered by frozen pools',list(observation_id=row$observation_id,status=status));outputs[[length(outputs)+1L]]<-list(observation_id=row$observation_id,index_date=row$index_date,pool_id=if(is.null(pool))NULL else pool$poo