.cr_rp_weighted<-function(values,weights){if(!length(values)||.cr_loss_sum(weights)==0)return(list(estimate=NULL,numerator=0,denominator=0,count=0,independent_episode_standard_error=NULL,observed_minimum=NULL,observed_maximum=NULL));keep<-weights>0;v<-values[keep];w<-weights[keep];denominator<-.cr_loss_sum(w);numerator<-.cr_loss_sum(vapply(seq_along(v),function(i).cr_loss_multiply(v[[i]],w[[i]]),numeric(1)));mean<-.cr_loss_sum(v*(w/denominator));n<-length(v);scale<-max(abs(v));se<-if(n<2)NULL else if(scale==0)0 else scale*sqrt(n/(n-1)*.cr_loss_sum(((w/denominator)*(v/scale-mean/scale))^2));if(!is.null(se)&&!is.finite(se)) .cr_error('NUMERICAL_FAILURE','Pool mean uncertainty outside finite range');list(estimate=mean,numerator=numerator,denominator=denominator,count=n,independent_episode_standard_error=se,observed_minimum=min(v),observed_maximum=max(v))}

estimate_pool_risk_parameters<-function(pool_assignments,cohort_outcomes,workouts,estimation_profile,evaluation_cutoff,calibration_id,calibration_version,context=NULL){assignments<-if(inherits(pool_assignments,'CalcResult'))pool_assignments$value else pool_assignments;if(!.cr_object(assignments)||!identical(assignments$artifact_type,'RETAIL_POOL_ASSIGNMENTS')) .cr_error('RETAIL_ARTIFACT','Frozen retail pool assignments required');unbound<-assignments;digest<-unbound$artifact_hash;unbound$artifact_hash<-NULL;if(!identical(digest,.cr_hash(unbound))) .cr_error('INTEGRITY_ERROR','Pool assignments differ from their binding');target<-.cr_rp_target(assignments$target);cutoff<-.cr_data_date(evaluation_cutoff,'evaluation_cutoff');ctx<-.cr_rf_cutoffs(evaluation_cutoff,evaluation_cutoff,context)$context;.cr_rp_context(ctx,target);if(.cr_data_date(assignments$information_cutoff,'assignment cutoff')>cutoff) .cr_error('RETAIL_DATE','Assignments not available at evaluation cutoff');.cr_rf_text(calibration_id,'calibration_id');.cr_rf_text(calibration_version,'calibration_version');profile<-estimation_profile;if(!.cr_object(profile)) .cr_error('RETAIL_ESTIMATION','Explicit dated estimation profile required');.cr_data_required(profile,c('profile_id','version','known_at','pd_weighting','lgd_weighting','ead_weighting','ccf_weighting','confidence','independence_assumption','minimum_pool_cases'));if(.cr_data_date(profile$known_at,'profile.known_at')>cutoff) .cr_error('RETAIL_DATE','Estimation profile unavailable at cutoff');if(!(profile$pd_weighting%in%c('default_unit','reference_exposure'))||!(profile$lgd_weighting%in%c('episode','ead'))||!(profile$ead_weighting%in%c('episode','reference_exposure'))||!(profile$ccf_weighting%in%c('episode','undrawn'))||profile$independence_assumption!='independent_default_units') .cr_error('RETAIL_ESTIMATION','Explicit supported parameter weightings and independent-default-unit inference assumption required');confidence<-.cr_rf_number(profile$confidence,'confidence');if(!(1e-8<=confidence&&confidence<=1-1e-8)) .cr_error('RETAIL_ESTIMATION','Confidence must lie inside [1e-8,1-1e-8]');minimum<-.cr_data_days(profile$minimum_pool_cases,'minimum_pool_cases',1);assigned<-setNames(assignments$assignments,vapply(assignments$assignments,`[[`,character(1),'observation_id'));rows<-.cr_data_rows(cohort_outcomes,'cohort outcomes');.cr_data_unique(rows,'observation_id','cohort outcomes');.cr_data_unique(rows,'default_unit_id','cohort default units');eligible<-list();excluded<-list();ids<-unlist(assignments$pool_ids,use.names=FALSE);pools<-setNames(rep(list(list()),length(ids)),ids)
 for(row in rows){.cr_data_required(row,c('default_unit_id','index_date','label_window_end','label_known_at','outcome_status','reference_exposure','reference_known_at'));if(!all(c('defaulted','default_date')%in%names(row))) .cr_error('RETAIL_TARGET','Outcome default flag and date require explicit nullable fields');assignment<-assigned[[row$observation_id]];if(is.null(assignment)||assignment$index_date!=row$index_date) .cr_error('RETAIL_TARGET','Outcome lacks same-observation/index-date pool assignment');index<-.cr_data_date(row$index_date,'index_date');end<-.cr_data_date(row$label_window_end,'label_window_end');known<-.cr_data_date(row$label_known_at,'label_known_at');reference_known<-.cr_data_date(row$reference_known_at,'reference_known_at');.cr_rf_number(row$reference_exposure,'reference_exposure',0);if(as.numeric(end-index)!=target$horizon||reference_known>index) .cr_error('RETAIL_DATE','Cohort horizon or frozen exposure weight invalid');if(!(row$outcome_status%in%c('MATURE','CENSORED','OPEN_HORIZON'))) .cr_error('RETAIL_TARGET','Explicit cohort maturity required');reason<-if(assignment$status!='COVERED')'UNASSIGNED_POOL'else if(row$outcome_status!='MATURE')row$outcome_status else if(end>cutoff||known>cutoff)'NOT_MATURE_AT_CUTOFF'else NULL;if(!is.null(reason)){excluded[[length(excluded)+1L]]<-list(observation_id=row$observation_id,reason=reason);next};if(known<end||!is.logical(row$defaulted)||length(row$defaulted)!=1||is.na(row$defaulted)) .cr_error('RETAIL_TARGET','Mature whole-horizon outcomes require explicit boolean default flag and receipt after horizon');if(row$defaulted){if(is.null(row$default_date)||!(index<.cr_data_date(row$default_date,'default_date')&&.cr_data_date(row$default_date,'default_date')<=end)) .cr_error('RETAIL_TARGET','Default date outside performing cohort horizon')}else if(!is.null(row$default_date)) .cr_error('RETAIL_TARGET','Nondefault outcome cannot carry default date');eligible[[row$observation_id]]<-row;pools[[assignment$pool_id]]<-c(pools[[assignment$pool_id]],list(row))}
 episodes<-.cr_data_rows(workouts,'workouts');.cr_data_unique(episodes,'episode_id','workouts');.cr_data_unique(episodes,'observation_id','workout observation');episode_results<-.cr_empty_object();workout_exclusions<-list();for(row in episodes){.cr_data_required(row,c('observation_id','default_date','default_known_at','ead_at_default','episode_status','valuation_known_at','recovery_cashflows','discount_curve','fx_contract','reference_date','reference_known_at','reference_drawn','reference_limit'));cohort<-eligible[[row$observation_id]];if(is.null(cohort)){workout_exclusions[[length(workout_exclusions)+1L]]<-list(episode_id=row$episode_id,reason='COHORT_NOT_ELIGIBLE');next};if(!cohort$defaulted||row$default_date!=cohort$default_date) .cr_error('RETAIL_TARGET','Workout must belong to the declared cohort default');known<-.cr_data_date(row$valuation_known_at,'valuation_known_at');default_known<-.cr_data_date(row$default_known_at,'default_known_at');if(known>cutoff||default_known>cutoff){workout_exclusions[[length(workout_exclusions)+1L]]<-list(episode_id=row$episode_id,reason='WORKOUT_NOT_KNOWN');next};if(known<default_known||default_known>.cr_data_date(cohort$label_known_at,'label_known_at')||row$reference_date!=cohort$index_date) .cr_error('RETAIL_DATE','Workout valuation receipt/reference differs from cohort convention');recoveries<-discount_recoveries(row$recovery_cashflows,row$discount_curve,row$fx_contract,default_date=row$default_date,evaluation_cutoff=row$valuation_known_at,reporting_currency=target$currency);lgd<-workout_lgd(row$ead_at_default,recoveries,episode_status=row$episode_status,default_date=row$default_date,evaluation_cutoff=row$valuation_known_at,currency=target$currency);ccf<-realized_ccf(row$reference_drawn,row$reference_limit,row$ead_at_default,reference_date=row$reference_date,default_date=row$default_date,reference_known_at=row$reference_known_at,default_known_at=row$default_known_at,evaluation_cutoff=evaluation_cutoff,currency=target$currency);episode_results[[row$observation_id]]<-list(episode_id=row$episode_id,lgd=lgd$value,ccf=ccf$value,recovery_valuation=recoveries$value)}
 table<-list();for(pool_id in names(pools)){cohort<-pools[[pool_id]];n<-length(cohort);d<-sum(vapply(cohort,`[[`,logical(1),'defaulted'));pd_selected<-.cr_rp_weighted(as.numeric(vapply(cohort,`[[`,logical(1),'defaulted')),vapply(cohort,function(r)if(profile$pd_weighting=='default_unit')1 else r$reference_exposure,numeric(1)));interval<-bound<-NULL;if(n>0){grade<-calibrate_grade_pd(n,d,grades=pool_id,monotonic=FALSE,confidence=confidence)$value$grades[[1]];interval<-list(estimate=grade$pd,lower=grade$lower,upper=grade$upper,count=n,defaults=d,weighting='default_unit',method='exact_binomial');bound<-low_default_bound(d,n,confidence=confidence,dependence='independent',pooling='none')$value$bounds[[1]]$upper_pd};lgd_values<-lgd_weights<-ead_values<-ead_weights<-ccf_values<-ccf_weights<-numeric();open_count<-zero_ead<-undefined_ccf<-missing_workouts<-0;episodes_used<-character();for(row in cohort){if(!row$defaulted)next;episode<-episode_results[[row$observation_id]];if(is.null(episode)){missing_workouts<-missing_workouts+1;next};episodes_used<-c(episodes_used,episode$episode_id);loss<-episode$lgd;conversion<-episode$ccf;ead<-loss$ead_at_default;ead_values<-c(ead_values,ead);ead_weights<-c(ead_weights,if(profile$ead_weighting=='episode')1 else row$reference_exposure);if(loss$episode_status=='OPEN')open_count<-open_count+1 else if(is.null(loss$economic_lgd))zero_ead<-zero_ead+1 else{lgd_values<-c(lgd_values,loss$economic_lgd);lgd_weights<-c(lgd_weights,if(profile$lgd_weighting=='episode')1 else ead)};if(is.null(conversion$ccf))undefined_ccf<-undefined_ccf+1 else{ccf_values<-c(ccf_values,conversion$ccf);ccf_weights<-c(ccf_weights,if(profile$ccf_weighting=='episode')1 else conversion$undrawn_at_reference)}};table[[length(table)+1L]]<-list(pool_id=pool_id,status=if(n>=minimum)'COHORT_SUPPORT_MET'else 'INSUFFICIENT_SUPPORT',mature_default_units=n,defaults=d,parameter_status=list(pd=if(pd_selected$denominator>0)'DEFINED'else 'ZERO_WEIGHT_OR_NO_MATURE_UNITS',lgd=if(.cr_loss_sum(lgd_weights)>0)'CLOSED_EPISODES_ONLY'else 'NO_DEFINED_CLOSED_EPISODES',ead=if(.cr_loss_sum(ead_weights)>0)'OBSERVED_DEFAULT_EPISODES'else 'NO_POSITIVE_WEIGHT_EXPOSURE_EPISODES',ccf=if(.cr_loss_sum(ccf_weights)>0)'DEFINED_UNDRAWN_REFERENCES'else 'NO_DEFINED_POSITIVE_WEIGHT_CCF'),pd_weighting=profile$pd_weighting,pd=pd_selected,unweighted_pd_exact_interval=interval,unweighted_pd_one_sided_upper=bound,lgd_weighting=profile$lgd_weighting,closed_workout_lgd=.cr_rp_weighted(lgd_values,lgd_weights),ead_weighting=profile$ead_weighting,default_conditioned_ead=.cr_rp_weighted(ead_values,ead_weights),ccf_weighting=profile$ccf_weighting,default_conditioned_ccf=.cr_rp_weighted(ccf_values,ccf_weights),open_workouts=open_count,zero_ead_closed_workouts=zero_ead,undefined_ccf_workouts=undefined_ccf,missing_default_workouts=missing_workouts,episode_ids=as.list(sort(episodes_used)))}
 value<-list(schema_version='1.0',artifact_type='CalibrationArtifact',calibration_type='RETAIL_POOL_RISK_PARAMETERS',calibration_id=calibration_id,calibration_version=calibration_version,base_model_id=assignments$model_id,base_model_version=assignments$model_version,base_model_hash=assignments$model_hash,assignments_hash=assignments$artifact_hash,target=target,evaluation_cutoff=evaluation_cutoff,estimation_profile=profile,pool_risk_table=table,aggregate_mature_default_units=sum(vapply(table,`[[`,numeric(1),'mature_default_units')),aggregate_defaults=sum(vapply(table,`[[`,numeric(1),'defaults')),provenance=assignments$provenance);value$artifact_hash<-.cr_hash(value);.cr_result(value,'retail_features.estimate_pool_risk_parameters','pool_risk_parameters',ctx,provenance=assignments$provenance,diagnostics=list(excluded_cohort_outcomes=excluded,excluded_workouts=workout_exclusions,missing_outcome_observation_ids=as.list(sort(setdiff(names(assigned),vapply(rows,`[[`,character(1),'observation_id')))),episode_results=episode_results,input_fingerprint=.cr_hash(list(cohort_outcomes=rows,workouts=episodes))),limitations=list('PD inference assumes independent homogeneous default units within frozen pools; exact intervals and upper bounds refer to unweighted unit counts, not exposure-weighted PD. Intervals are conditional on chosen pools and do not account for pool-selection uncertainty or establish long-run/TTC calibration. LGD estimates use only observed closed workouts; open workouts remain separate and no future recoveries are invented. EAD and CCF condition on observed default and available exposure records. Reported episode standard errors describe independent-episode weighted means; they do not resolve censoring, missing-workout selection or dependence. Sparse pools retain descriptive estimates with explicit insufficient-support status.'))}
